23	    const unsigned int kAllCategories = 0xFFFFFFFFu;
24	
25	    // Finite stand-in for "as far as the world goes". Chipmunk needs a real number for the
26	    // nearest-point queries, and an infinite one would poison the returned distance, so the
27	    // horizon is set well beyond the extents of a normal cocos2d-x scene instead.
28	    const float kQueryHorizon = 100000.0f;
29	
30	    // Hits this close to a segment end are treated as touching the endpoint, not as crossing it.
31	    const float kAlphaEpsilon = 1e-4f;
32	
33	    // Path clearance is sampled along each leg; the step keeps short legs cheap and the cap
34	    // keeps a very long leg from turning into an unbounded number of queries.
35	    const float kClearanceSampleStep = 16.0f;
36	    const int kMaxClearanceSamples = 64;
37	
38	    // Upper bound on the samples taken per axis by findOpenPositions.
39	    const int kMaxGridSamplesPerAxis = 256;
40	
41	    // A mask of 0 or 0xFFFFFFFF means "every category". Any other mask is passed as both the
42	    // categories and the acceptance mask, so a shape matches when it shares a bit with it.
43	    cpShapeFilter makeCategoryFilter(unsigned int categoryMask)
44	    {
45	        if (categoryMask == 0u || categoryMask == kAllCategories)
46	        {
47	            return CP_SHAPE_FILTER_ALL;
48	        }
49	
50	        return cpShapeFilterNew(CP_NO_GROUP,
51	                                static_cast<cpBitmask>(categoryMask),
52	                                static_cast<cpBitmask>(categoryMask));
53	    }
54	
55	    PhysicsShape* toPhysicsShape(const cpShape* shape)
56	    {
57	        if (shape == nullptr)
58	        {
59	            return nullptr;
60	        }
61	
62	        return static_cast<PhysicsShape*>(cpShapeGetUserData(const_cast<cpShape*>(shape)));
63	    }
64	
65	    PhysicsBody* toPhysicsBody(const cpShape* shape)
66	    {
67	        PhysicsShape* physicsShape = toPhysicsShape(shape);
68	        return physicsShape == nullptr ? nullptr : physicsShape->getBody();
69	    }
70	
71	    template <typename T>
72	    void appendUnique(std::vector<T>& container, T value)
73	    {
74	        if (std::find(container.begin(), container.end(), value) == container.end())
75	        {
76	            container.push_back(value);
77	        }
78	    }
79	
80	    // Distance from a point to the closest matching surface, or -1 when nothing is within
81	    // maxDistance. A point inside a shape reports 0 so that a negative value never means "inside".
82	    float nearestSurfaceDistance(cpSpace* space, cpVect point, cpShapeFilter filter, float maxDistance)
83	    {
84	        if (space == nullptr)
85	        {
86	            return -1.0f;
87	        }
88	
89	        cpPointQueryInfo info = { nullptr, cpvzero, 0.0, cpvzero };
90	        if (cpSpacePointQueryNearest(space, point, maxDistance, filter, &info) == nullptr)
91	        {
92	            return -1.0f;
93	        }
94	
95	        return info.distance > 0.0 ? PhysicsHelper::cpfloat2float(info.distance) : 0.0f;
96	    }
97	
98	    int clearanceSampleCount(float length)
99	    {
100	        if (length <= 0.0f)
101	        {
102	            return 2;
103	        }
104	
105	        int count = static_cast<int>(length / kClearanceSampleStep) + 2;
106	        return count > kMaxClearanceSamples ? kMaxClearanceSamples : count;
107	    }
