109	    void collectSegmentHit(cpShape* shape, cpVect point, cpVect normal, cpFloat alpha, void* data)
110	    {
111	        std::vector<PhysicsSegmentQueryResult>* results = static_cast<std::vector<PhysicsSegmentQueryResult>*>(data);
112	        PhysicsShape* physicsShape = toPhysicsShape(shape);
113	
114	        if (results == nullptr || physicsShape == nullptr)
115	        {
116	            return;
117	        }
118	
119	        PhysicsSegmentQueryResult hit;
120	        hit.shape = physicsShape;
121	        hit.point = PhysicsHelper::cpv2point(point);
122	        hit.normal = PhysicsHelper::cpv2point(normal);
123	        hit.alpha = PhysicsHelper::cpfloat2float(alpha);
124	
125	        results->push_back(hit);
126	    }
