131	        PhysicsShape* physicsShape = toPhysicsShape(shape);
132	
133	        if (results == nullptr || physicsShape == nullptr)
134	        {
135	            return;
136	        }
137	
138	        PhysicsNearestResult hit;
139	        hit.shape = physicsShape;
140	        hit.point = PhysicsHelper::cpv2point(point);
