161	    void collectBody(cpShape* shape, void* data)
162	    {
163	        std::vector<PhysicsBody*>* results = static_cast<std::vector<PhysicsBody*>*>(data);
164	        PhysicsBody* body = toPhysicsBody(shape);
165	
166	        if (results == nullptr || body == nullptr)
167	        {
168	            return;
169	        }
170	
171	        appendUnique(*results, body);
172	    }
