357	std::vector<PhysicsSegmentQueryResult> PhysicsWorldQuery::querySegment(const Vec2& start, const Vec2& end, float radius, unsigned int categoryMask)
358	{
359	    std::vector<PhysicsSegmentQueryResult> results;
360	
361	    if (!_initialized || _space == nullptr)
362	    {
363	        return results;
364	    }
365	
366	    cpSpaceSegmentQuery(_space,
367	                        PhysicsHelper::point2cpv(start),
368	                        PhysicsHelper::point2cpv(end),
369	                        radius < 0.0f ? 0.0f : radius,
370	                        makeCategoryFilter(categoryMask),
371	                        collectSegmentHit,
372	                        &results);
373	
374	    // Near hits first; a stable sort leaves equal alphas in the order they were collected.
375	    std::stable_sort(results.begin(), results.end(),
376	                     [](const PhysicsSegmentQueryResult& a, const PhysicsSegmentQueryResult& b) {
377	                         return a.alpha < b.alpha;
378	                     });
379	
380	    return results;
381	}
