383	PhysicsSegmentQueryResult PhysicsWorldQuery::querySegmentFirst(const Vec2& start, const Vec2& end, float radius, unsigned int categoryMask)
384	{
385	    // Miss reads as "the ray survived the whole segment": alpha 1, no shape, point at the end.
386	    PhysicsSegmentQueryResult result = { nullptr, end, Vec2::ZERO, 1.0f };
387	
388	    if (!_initialized || _space == nullptr)
389	    {
390	        return result;
391	    }
392	
393	    cpSegmentQueryInfo info = { nullptr, PhysicsHelper::point2cpv(end), cpvzero, 1.0 };
394	    cpShape* shape = cpSpaceSegmentQueryFirst(_space,
395	                                              PhysicsHelper::point2cpv(start),
396	                                              PhysicsHelper::point2cpv(end),
397	                                              radius < 0.0f ? 0.0f : radius,
398	                                              makeCategoryFilter(categoryMask),
399	                                              &info);
400	
401	    PhysicsShape* physicsShape = toPhysicsShape(shape);
402	    if (physicsShape == nullptr)
403	    {
404	        return result;
405	    }
406	
407	    result.shape = physicsShape;
408	    result.point = PhysicsHelper::cpv2point(info.point);
409	    result.normal = PhysicsHelper::cpv2point(info.normal);
410	    result.alpha = PhysicsHelper::cpfloat2float(info.alpha);
411	
412	    return result;
413	}
