122	int PhysicsHelper::computeConvexHull(const Vec2* points, int count, Vec2* outHull)
123	{
124	    if (points == nullptr || outHull == nullptr || count <= 0)
125	        return 0;
126	
127	    std::vector<Vec2> sorted(points, points + count);
128	    std::sort(sorted.begin(), sorted.end(), [](const Vec2& a, const Vec2& b) {
129	        return a.x < b.x || (a.x == b.x && a.y < b.y);
130	    });
131	    sorted.erase(std::unique(sorted.begin(), sorted.end(), [](const Vec2& a, const Vec2& b) {
132	        return a.x == b.x && a.y == b.y;
133	    }), sorted.end());
134	
135	    const int n = static_cast<int>(sorted.size());
136	    if (n < 3)
137	    {
138	        for (int i = 0; i < n; ++i)
139	        {
140	            outHull[i] = sorted[i];
141	        }
142	        return n;
143	    }
144	
145	    // Andrew's monotone chain: lower hull left to right, then upper hull back.
146	    std::vector<Vec2> chain(2 * n);
147	    int k = 0;
148	
149	    for (int i = 0; i < n; ++i)
150	    {
151	        while (k >= 2 && (chain[k - 1] - chain[k - 2]).cross(sorted[i] - chain[k - 1]) <= 0.0f)
152	        {
153	            --k;
154	        }
155	        chain[k++] = sorted[i];
156	    }
157	
158	    const int lowerCount = k + 1;
159	    for (int i = n - 2; i >= 0; --i)
160	    {
161	        while (k >= lowerCount && (chain[k - 1] - chain[k - 2]).cross(sorted[i] - chain[k - 1]) <= 0.0f)
162	        {
163	            --k;
164	        }
165	        chain[k++] = sorted[i];
166	    }
167	
168	    const int hullCount = k - 1;
169	    for (int i = 0; i < hullCount; ++i)
170	    {
171	        outHull[i] = chain[i];
172	    }
173	
174	    return hullCount;
175	}
