177	Vec2 PhysicsHelper::computePolygonCenter(const Vec2* verts, int count)
178	{
179	    if (verts == nullptr || count <= 0)
180	        return Vec2::ZERO;
181	
182	    if (count == 1)
183	        return verts[0];
184	
185	    if (count == 2)
186	        return (verts[0] + verts[1]) * 0.5f;
187	
188	    if (polygonArea(verts, count) > kHelperEpsilon)
189	    {
190	        std::vector<cpVect> cpvs(count);
191	        points2cpvs(verts, cpvs.data(), count);
192	        return cpv2point(cpCentroidForPoly(count, cpvs.data()));
193	    }
194	
195	    // Degenerate (zero area) outline, fall back to the average of the vertices.
196	    Vec2 sum(0.0f, 0.0f);
197	    for (int i = 0; i < count; ++i)
198	    {
199	        sum += verts[i];
200	    }
201	
202	    return sum / static_cast<float>(count);
203	}
204	
205	bool PhysicsHelper::isPolygonConvex(const Vec2* verts, int count)
206	{
207	    if (verts == nullptr || count < 3)
208	        return false;
209	
210	    int sign = 0;
211	    for (int i = 0; i < count; ++i)
212	    {
213	        const Vec2& a = verts[i];
214	        const Vec2& b = verts[(i + 1) % count];
215	        const Vec2& c = verts[(i + 2) % count];
216	        const float turn = (b - a).cross(c - b);
217	
218	        if (turn > kHelperEpsilon)
219	        {
220	            if (sign < 0)
221	                return false;
222	            sign = 1;
223	        }
224	        else if (turn < -kHelperEpsilon)
225	        {
226	            if (sign > 0)
227	                return false;
228	            sign = -1;
229	        }
230	    }
231	
232	    return sign != 0;
233	}
