57	    // resolvable as soon as it owns a body, which is why callers re-resolve lazily.
58	    cpSpace* resolveSpace(PhysicsWorld* world)
59	    {
60	        if (world == nullptr)
61	        {
62	            return nullptr;
63	        }
64	
65	        const Vector<PhysicsBody*>& bodies = world->getAllBodies();
66	        for (const auto& body : bodies)
67	        {
68	            if (body == nullptr)
69	            {
70	                continue;
71	            }
72	
73	            cpBody* cpBodyRef = body->getCPBody();
74	            if (cpBodyRef == nullptr)
75	            {
76	                continue;
77	            }
78	
79	            cpSpace* space = cpBodyGetSpace(cpBodyRef);
80	            if (space != nullptr)
81	            {
82	                return space;
83	            }
84	        }
